styles:
.fx-controls {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem 1.25rem;
      align-items: flex-end;
      margin-bottom: 0.85rem;
      padding: 0.75rem 0.85rem;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius, 0.5em);
      background: var(--is-bg-elev);
    }
    .fx-controls label.fx-field {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
      font-size: 0.75rem;
      color: var(--is-text-soft);
      min-width: 7.5rem;
    }
    .fx-controls select {
      font: inherit;
      font-size: 0.875rem;
      color: var(--is-text);
      background: var(--is-bg);
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius-sm, 0.35em);
      padding: 0.35rem 0.5rem;
    }
    .fx-bools {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem 1.1rem;
      align-items: center;
    }
    .fx-attr {
      margin: 0.35rem 0 0.85rem;
      font-size: 0.8rem;
      color: var(--is-text-soft);
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      word-break: break-all;
    }
    .fx-stage {
      resize: both;
      overflow: auto;
      display: flex;
      align-items: stretch;
      box-sizing: border-box;
      min-width: 10rem;
      min-height: 5.5rem;
      width: min(100%, 28rem);
      height: 9rem;
      padding: 0.65rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius, 0.5em);
      background:
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--is-border) 28%, transparent) 0 7px,
          transparent 7px 14px),
        var(--is-bg);
    }
    .fx-stage > is-flex-layout {
      outline: 1px solid color-mix(in srgb, var(--is-brand, #3b82f6) 45%, transparent);
      outline-offset: -1px;
      border-radius: 0.35em;
      background: color-mix(in srgb, var(--is-bg-elev) 88%, transparent);
      padding: 0.35rem;
      box-sizing: border-box;
      min-height: 0;
    }
    .fx-stage--tall { height: 12rem; width: min(100%, 22rem); }
    .fx-stage--wide { width: min(100%, 36rem); height: 7.5rem; }
    .fx-hint {
      margin: 0.4rem 0 0;
      font-size: 0.75rem;
      color: var(--is-text-dim);
    }
    .fx-chip {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      box-sizing: border-box;
      padding: 0.35rem 0.55rem;
      border-radius: 0.55em;
      border: 1px solid color-mix(in srgb, var(--is-border) 70%, transparent);
      background: var(--is-bg-elev);
      color: var(--is-text);
      font-size: 1.05rem;
      line-height: 1.2;
      white-space: nowrap;
      user-select: none;
    }
    .fx-chip .lbl {
      font-size: 0.78rem;
      font-weight: 600;
      color: var(--is-text-soft);
    }
    .fx-chip--sm { font-size: 0.95rem; padding: 0.2rem 0.4rem; }
    .fx-chip--md { font-size: 1.15rem; padding: 0.45rem 0.65rem; }
    .fx-chip--lg {
      font-size: 1.45rem;
      padding: 0.6rem 0.85rem;
      flex-direction: column;
      align-items: flex-start;
    }
    .fx-chip--lg .lbl { font-size: 0.72rem; }
    .fx-chip--xl {
      font-size: 1.75rem;
      padding: 0.75rem 1rem;
      min-height: 3.25rem;
    }
    .fx-demo-stack { display: flex; flex-direction: column; gap: 1.25rem; }
    .fx-demo-block h3 {
      margin: 0 0 0.35rem;
      font-size: 0.95rem;
      font-weight: 650;
    }
